    final old = _engine;
    _engine = null;
    // A fresh boot re-arms the one-shot unwired-voxel diagnostic: start()
    // restarts the SAME instance, so a flag spent by an earlier boot would
    // silence a genuinely-unwired state after a reload (gh-1441 review).

