  @visibleForTesting
  static void reset() {
    _lines.clear();
    _env = null;
    _fileBytes = 0;
    _writes = Future<void>.value();
  }

  /// Waits for the queued persistence writes — tests only.
  @visibleForTesting
  static Future<void> flush() => _writes;

