  /// The JS entry file inside the app folder (`apps/<id>/`) that [start]
  /// runs — [defaultEntryFile] for the full app, the tile entry
  /// ([JsTileWidgetInfo.entry]) when the engine powers a launcher live tile.
  final String entryFile;
