static bool _containsVoxelNode(Object? node, {required int depth}) {
  if (depth > 64) return false;
  if (node is Map) {
    return node['type'] == 'voxel' ||
        node.values.any((value) => _containsVoxelNode(value, depth: depth + 1));
  }
