String topLevelArgs(String args) {
  final out = StringBuffer();
  var depth = 0;
  for (var i = 0; i < args.length; i++) {
    final ch = args[i];
    if (ch == '(') {
      depth++;
      continue;
    }
    if (ch == ') {
      if (depth > 0) depth--;
      continue;
    }
    if (depth == 0) out.write(ch);
  }
  return out.toString();
}
