```

New:

```dart
  /// Whether [node] — a JSON widget tree — contains a `voxel` node
  /// anywhere (recursing through child maps/lists, depth-capped).
  ///
  /// Complexity stays ≤5 (the CI app-crap-gate measures this file against
  /// the ubuntu shard coverage, where the walk is unreachable — a live
  /// engine with a null world needs a backend-less host — so an uncovered
  /// CC-9 version measured CRAP 90 > 30 and failed the ratchet on run
  /// 37974606427; see [containsVoxelNodeForTest] for the direct pins).
  static bool _containsVoxelNode(Object? node, {required int depth}) {
    if (depth > 64) return false;
    if (node is Map) {
      return node['type'] == 'voxel' ||
          node.values
              .any((value) => _containsVoxelNode(value, depth: depth + 1));
    }
    if (node is List) {
      return node.any((value) => _containsVoxelNode(value, depth: depth + 1));
    }
    return false;
  }

  /// Direct unit seam for the JSON-tree walk behind
